    const result={key:ecpayRepostKey(row),accountNumber:row.accountNumber,name:row.name,office:row.office,billMonth:row.billMonth,amount:Number(row.amount),olderBillCount:billCount-newerCount,newerBillCount:newerCount,newerTotal,currentUnpaidTotal:fullTotal,eligible:isEligible,reason};
